// Receives execution pings from webhook.lua and relays them to the per-script
// Discord webhook. The script -> url map lives in the DISCORD_WEBHOOKS secret
// (generated by scripts-util/gen-webhook-secret.cjs), never in this repo.

const WEBHOOKS: Record<string, string> = JSON.parse(
    Deno.env.get("DISCORD_WEBHOOKS") ?? "{}",
);

const COLOR = 0x5865f2;

interface Payload {
    Script?: string;
    User?: string;
    UserId?: number;
    Game?: string;
    Executor?: string;
    PlaceId?: number;
}

function json(status: number, body: unknown): Response {
    return new Response(JSON.stringify(body), {
        status,
        headers: { "Content-Type": "application/json" },
    });
}

function text(value: unknown, max: number): string {
    if (typeof value !== "string") return "";
    return value.trim().slice(0, max);
}

// Roblox is the source of truth for the display name so a modified client
// cannot attribute an execution to someone else. Best effort: a failed lookup
// must never drop a real execution.
async function resolveUser(userId: number, fallback: string): Promise<string> {
    try {
        const res = await fetch(`https://users.roblox.com/v1/users/${userId}`, {
            headers: { Accept: "application/json" },
            signal: AbortSignal.timeout(4000),
        });

        if (res.ok) {
            const body = await res.json();
            if (typeof body?.name === "string" && body.name) return body.name;
        }
    } catch {
        // fall through to the name the client sent
    }

    return fallback || `User ${userId}`;
}

Deno.serve(async (req: Request) => {
    if (req.method === "OPTIONS") return new Response(null, { status: 204 });
    if (req.method !== "POST") return json(405, { error: "Method not allowed" });

    let body: Payload;

    try {
        body = await req.json();
    } catch {
        return json(400, { error: "Invalid JSON" });
    }

    if (!body || typeof body !== "object") {
        return json(400, { error: "Invalid JSON" });
    }

    const script = text(body.Script, 100);

    if (!script) return json(400, { error: "Missing Script field" });

    const webhook = WEBHOOKS[script];

    if (!webhook) {
        return json(404, { error: "No webhook configured for this script", script });
    }

    const userId = Number(body.UserId);

    if (!Number.isInteger(userId) || userId <= 0) {
        return json(200, { sent: false, reason: "Invalid user" });
    }

    const user = await resolveUser(userId, text(body.User, 32));
    const game = text(body.Game, 100) || "Unknown";
    const executor = text(body.Executor, 100) || "Unknown";
    const placeId = Number(body.PlaceId) || 0;

    const message = {
        embeds: [
            {
                author: {
                    name: `${user} (${userId})`,
                    icon_url:
                        `https://www.roblox.com/headshot-thumbnail/image?userId=${userId}&width=420&height=420&format=png`,
                },
                title: script,
                color: COLOR,
                fields: [
                    { name: "Game", value: game, inline: true },
                    { name: "Executor", value: executor, inline: true },
                    { name: "Place ID", value: String(placeId), inline: true },
                ],
                timestamp: new Date().toISOString(),
            },
        ],
    };

    const res = await fetch(webhook, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(message),
    });

    if (!res.ok) {
        const detail = await res.text();
        console.error("Discord rejected webhook", script, res.status, detail.slice(0, 300));
        return json(502, { error: "Discord rejected the webhook", status: res.status });
    }

    return json(200, { sent: true, script });
});
